CREATE TABLE "api_clients" ("id" SERIAL NOT NULL, "name" character varying(150) NOT NULL, "client_id" character varying(40) NOT NULL, "secret_hash" character varying NOT NULL, "secret_hint" character varying(8) NOT NULL, "scopes" text NOT NULL, "is_active" boolean NOT NULL DEFAULT true, "expires_at" TIMESTAMP, "last_used_at" TIMESTAMP, "note" character varying(255), "create_by" character varying(50) NOT NULL DEFAULT 'system', "create_date" TIMESTAMP NOT NULL DEFAULT now(), CONSTRAINT "PK_ef2d5ef0eb5e9a6ddc67cfa310e" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "IDX_2cc528aa877e26788808e58185" ON "api_clients" ("client_id");
